+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+
+/**
+ * Narrows the customer list by name and by status.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *   <li><b>name</b>: the text is split on whitespace into terms, and every term
+ *       must be a substring of the first name or the last name. Case and accents
+ *       are ignored. An empty name matches everyone.</li>
+ *   <li><b>status</b>: with no statuses selected every status matches, otherwise
+ *       the customer's status must be one of the selected ones.</li>
+ * </ul>
+ *
+ * @param name     the text typed into the name filter; may be blank
+ * @param statuses the selected statuses; empty means "all statuses"
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    /** Returns a predicate that tests customers against this filter. */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = terms();
+        Predicate<Customer> byName = customer -> {
+            String first = fold(customer.firstName());
+            String last = fold(customer.lastName());
+            return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+        };
+        Predicate<Customer> byStatus = customer -> statuses.isEmpty() || statuses.contains(customer.status());
+        return byName.and(byStatus);
+    }
+
+    private List<String> terms() {
+        return Arrays.stream(fold(name).trim().split("\\s+"))
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
