+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void launchBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void closeBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @BeforeEach
+    void openPage() {
+        page = browser.newPage();
+    }
+
+    @Test
+    void typingNarrowsTheListAndTheAddressBarFollows() {
+        open("/");
+        waitForSummary("Showing 500 of 500");
+
+        typeName("vir");
+        waitForSummary("Showing 15 of 500");
+        assertEquals(15, gridSize());
+        waitForUrl("/?name=vir");
+
+        typeName("");
+        waitForSummary("Showing 500 of 500");
+        waitForUrl("/");
+    }
+
+    @Test
+    void statusFilterIsWrittenToTheAddressBarInDeclarationOrder() {
+        open("/");
+        waitForSummary("Showing 500 of 500");
+
+        page.locator("vaadin-multi-select-combo-box").click();
+        page.getByRole(AriaRole.OPTION,
+                new Page.GetByRoleOptions().setName("CLOSED")).click();
+        page.getByRole(AriaRole.OPTION,
+                new Page.GetByRoleOptions().setName("ACTIVE")).click();
+        page.keyboard().press("Escape");
+
+        waitForSummary("Showing 333 of 500");
+        waitForUrl("/?status=ACTIVE,CLOSED");
+    }
+
+    @Test
+    void openingTheAddressRestoresTheFilter() {
+        open("/?name=vir&status=ACTIVE,CLOSED");
+
+        waitForSummary("Showing 10 of 500");
+        assertEquals("vir", nameInput().inputValue());
+        assertEquals(10, gridSize());
+    }
+
+    @Test
+    void typingAWordCostsAFewBackendQueriesNotOnePerKeystroke() {
+        open("/");
+        waitForSummary("Showing 500 of 500");
+
+        int historyBefore = ((Number) page.evaluate("history.length")).intValue();
+        queryLog.clear();
+        typeName("josephine");
+        waitForSummary("Showing 12 of 500");
+        assertEquals(historyBefore, ((Number) page.evaluate("history.length")).intValue(),
+                "typing must replace the address, not add history entries");
+
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "typing nine letters ran " + queryLog.countQueries().size() + " count queries");
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "typing nine letters ran " + queryLog.pageQueries().size() + " page queries");
+    }
