+    }
+
+    /** Waits for the address bar, which the view updates from the client after the summary. */
+    private void waitForUrl(String pathAndQuery) {
+        String expected = "http://localhost:" + port + pathAndQuery;
+        page.waitForFunction("url => location.href === url", expected);
+        assertEquals(expected, page.url());
+    }
+
+    private Locator nameInput() {
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private void typeName(String name) {
+        Locator input = nameInput();
+        input.fill("");
+        if (!name.isEmpty()) {
+            input.pressSequentially(name);
+        }
+    }
+
+    private void waitForSummary(String text) {
+        page.getByText(text, new Page.GetByTextOptions().setExact(true))
+                .waitFor(new Locator.WaitForOptions().setTimeout(10_000));
